(function(root){'use strict';
function dayKey(t=Date.now()){const d=new Date(t);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function dayAfter(n,now=Date.now()){const d=new Date(now);d.setDate(d.getDate()+n);d.setHours(0,0,0,0);return d.getTime();}
function schedule(previous,score,now=Date.now()){
 if(!Number.isInteger(score)||score<1||score>10)throw Error('评分应为 1–10 的整数');
 const p=previous||{},q=score<=3?1:score<=5?2:score===6?3:score<=8?4:5;
 const ease=Math.max(1.3,Math.min(3.5,(p.ease||2.5)+(.1-(5-q)*(.08+(5-q)*.02))));
 let interval,successes,due,stage;
 if(score<=3){interval=0;successes=0;due=now+10*60*1000;stage='learning';}
 else if(score<=5){interval=1;successes=0;due=dayAfter(1,now);stage='learning';}
 else {successes=(p.successes||0)+1;const first={6:1,7:1,8:2,9:3,10:4};const multiplier={6:.65,7:.85,8:1,9:1.1,10:1.25};interval=successes===1?first[score]:Math.min(365,Math.max((p.interval||1)+1,Math.ceil((p.interval||1)*ease*multiplier[score])));due=dayAfter(interval,now);stage='review';}
 return {ease,interval,successes,due,stage,lastScore:score,lastReview:now,reviews:(p.reviews||0)+1,lapses:(p.lapses||0)+(score<=5?1:0)};
}
function normalize(s){return s.normalize('NFC').toLocaleLowerCase().replace(/[’‘`]/g,"'").replace(/[‐‑–—]/g,'-').replace(/[.,!?;:«»“”"()[\]，。！？；：、]/g,' ').replace(/\s+/g,' ').trim();}
function distance(a,b){let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const old=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=old;}}return row[b.length];}
function match(answer,reference){const a=normalize(answer),b=normalize(reference);if(!a)return {score:1,percent:0,exact:false,accentOnly:false};if(a===b)return {score:10,percent:100,exact:true,accentOnly:false};const strip=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');const accentOnly=strip(a)===strip(b);const ratio=Math.max(0,1-distance(a,b)/Math.max(a.length,b.length));return {score:accentOnly?9:Math.max(1,Math.min(9,Math.round(ratio*10))),percent:Math.round(ratio*100),exact:false,accentOnly};}
function wordDiff(answer,reference){const a=normalize(answer).split(' '),b=reference.split(/\s+/);const norm=b.map(normalize);const dp=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));for(let i=a.length-1;i>=0;i--)for(let j=b.length-1;j>=0;j--)dp[i][j]=a[i]===norm[j]?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]);let i=0,j=0;const same=new Set();while(i<a.length&&j<b.length){if(a[i]===norm[j]){same.add(j);i++;j++;}else if(dp[i+1][j]>=dp[i][j+1])i++;else j++;}return b.map((word,k)=>({word,match:same.has(k)}));}
function todayIds(history,now=Date.now()){return new Set(history.filter(h=>dayKey(h.at)===dayKey(now)).map(h=>h.id));}
function dailyCounts(history,now=Date.now()){
 const first=new Map();for(const h of history){if(!first.has(h.id)||h.at<first.get(h.id).at)first.set(h.id,h);}
 const today=dayKey(now),newIds=new Set(),reviewIds=new Set();
 for(const h of history){if(dayKey(h.at)!==today)continue;if(first.get(h.id)===h)newIds.add(h.id);else reviewIds.add(h.id);}
 return {newIds,reviewIds};
}
function nextPracticeCard(cards,state,{mode='daily',scope='all',extra=false}={},now=Date.now()){
 const due=dueCards(cards,state.progress,now);if(due.length)return due[0];
 if(mode==='due'||(!extra&&dailyCounts(state.history,now).newIds.size>=state.settings.goal))return null;
 return cards.filter(c=>!state.progress[c.id]&&(scope==='all'||c.group===scope)).sort((a,b)=>Number(b.star)-Number(a.star))[0]||null;
}
function dueCards(cards,progress,now=Date.now()){return cards.filter(c=>progress[c.id]&&progress[c.id].due<=now).sort((a,b)=>progress[a.id].due-progress[b.id].due);}
function initialState(){return {version:1,settings:{goal:20,time:'20:00'},progress:{},history:[],notes:{},draft:null,lastNotification:null};}
function validateState(raw,ids){if(!raw||raw.version!==1||!raw.settings||!Number.isInteger(raw.settings.goal)||raw.settings.goal<1||raw.settings.goal>100||!/^([01]\d|2[0-3]):[0-5]\d$/.test(raw.settings.time)||!raw.progress||typeof raw.progress!=='object'||Array.isArray(raw.progress)||!Array.isArray(raw.history)||raw.history.length>100000)throw Error('备份格式不正确');const result=initialState();if(raw.bubbles!==undefined){const B=root.ParoleBubbles||(typeof require==='function'?require('./bubbles.js'):null);result.bubbles=B.validate(raw.bubbles);}if(raw.notes!==undefined){if(!raw.notes||typeof raw.notes!=='object'||Array.isArray(raw.notes))throw Error('备份笔记格式不正确');for(const [id,note] of Object.entries(raw.notes)){if(!ids.has(id)||typeof note!=='string'||note.length>10000)throw Error('备份含有无效笔记');result.notes[id]=note;}}result.settings={goal:raw.settings.goal,time:raw.settings.time};for(const k of ['sourceLanguage','targetLanguage'])if(raw.settings[k]!==undefined){if(!['zh','en','fr','es','de','it','pt','ja','ko','ar','ru','hi'].includes(raw.settings[k]))throw Error('Invalid learning language');result.settings[k]=raw.settings[k];}for(const [id,p] of Object.entries(raw.progress)){if(!ids.has(id)||!p||!Number.isFinite(p.due)||p.due<0||!Number.isFinite(p.ease)||p.ease<1.3||p.ease>3.5||!Number.isInteger(p.lastScore)||p.lastScore<1||p.lastScore>10||!Number.isFinite(p.lastReview)||p.lastReview<0||!Number.isInteger(p.interval)||p.interval<0||p.interval>365||!Number.isInteger(p.successes)||p.successes<0||!Number.isInteger(p.reviews)||p.reviews<1||!Number.isInteger(p.lapses)||p.lapses<0||!['learning','review'].includes(p.stage))throw Error('备份含有无效学习记录');result.progress[id]={ease:p.ease,interval:p.interval,successes:p.successes,due:p.due,stage:p.stage,lastScore:p.lastScore,lastReview:p.lastReview,reviews:p.reviews,lapses:p.lapses};}result.history=raw.history.map(h=>{if(!h||!ids.has(h.id)||!Number.isFinite(h.at)||h.at<0||!Number.isInteger(h.score)||h.score<1||h.score>10)throw Error('备份含有无效历史');const entry={id:h.id,at:h.at,score:h.score};for(const field of ['answer','reference']){if(h[field]!==undefined){if(typeof h[field]!=='string'||h[field].length>2000)throw Error('备份含有无效表达输入');entry[field]=h[field];}}return entry;});if(raw.draft&&ids.has(raw.draft.id)&&typeof raw.draft.answer==='string'&&raw.draft.answer.length<=2000)result.draft={id:raw.draft.id,answer:raw.draft.answer,...(raw.draft.inputMode==='voice'?{inputMode:'voice'}:{}),revealed:!!raw.draft.revealed,score:Number.isInteger(raw.draft.score)&&raw.draft.score>=1&&raw.draft.score<=10?raw.draft.score:null};if(typeof raw.lastNotification==='string')result.lastNotification=raw.lastNotification;return result;}
function foldLine(line){let output='',part='',size=0;for(const ch of line){const bytes=new TextEncoder().encode(ch).length;if(size+bytes>75){output+=part+'\r\n';part=' ';size=1;}part+=ch;size+=bytes;}return output+part;}
function calendar(time,url,now=Date.now(),language='zh'){const escape=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const d=new Date(now),[h,m]=time.split(':').map(Number);d.setHours(h,m,0,0);if(d.getTime()<now)d.setDate(d.getDate()+1);const stamp=x=>`${x.getFullYear()}${String(x.getMonth()+1).padStart(2,'0')}${String(x.getDate()).padStart(2,'0')}T${String(x.getHours()).padStart(2,'0')}${String(x.getMinutes()).padStart(2,'0')}00`;const end=new Date(d.getTime()+15*60000);return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Parole//Language Practice//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:parole-daily-practice@parole.local','DTSTAMP:'+new Date(now).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART:'+stamp(d),'DTEND:'+stamp(end),'RRULE:FREQ=DAILY','SUMMARY:'+escape(language==='en'?'Parole · Language practice':'Parole · 语言表达复习'),'DESCRIPTION:'+escape((language==='en'?'Open Parole: review due expressions, then practise new ones.\n':'打开 Parole，先复习到期表达，再练习新句子。\n')+url),'BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:'+escape(language==='en'?'Start with one expression today.':'今天的练习，从一句开始。'),'END:VALARM','END:VEVENT','END:VCALENDAR'].map(foldLine).join('\r\n')+'\r\n';}
const api={dayKey,dayAfter,schedule,normalize,match,wordDiff,todayIds,dailyCounts,nextPracticeCard,dueCards,initialState,validateState,calendar};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.ParoleCore=api;
})(typeof window!=='undefined'?window:globalThis);
